// CreateConstraint creates a constraint
func (s *SegmentStorage) CreateConstraint(ctx context.Context, r *flipt.CreateConstraintRequest) (*flipt.Constraint, error) {
	s.logger.WithField("request", r).Debug("create constraint")

	var (
		operator = strings.ToLower(r.Operator)
		now      = proto.TimestampNow()
		c        = &flipt.Constraint{
			Id:         uuid.Must(uuid.NewV4()).String(),
			SegmentKey: r.SegmentKey,
			Type:       r.Type,
			Property:   r.Property,
			Operator:   operator,
			Value:      r.Value,
			CreatedAt:  now,
			UpdatedAt:  now,
		}
	)

	// validate operator works for this constraint type
	switch c.Type {
	case flipt.ComparisonType_STRING_COMPARISON_TYPE:
		if _, ok := stringOperators[c.Operator]; !ok {
			return nil, ErrInvalidf("constraint operator %q is not valid for type string", r.Operator)
		}
	case flipt.ComparisonType_NUMBER_COMPARISON_TYPE:
		if _, ok := numberOperators[c.Operator]; !ok {
			return nil, ErrInvalidf("constraint operator %q is not valid for type number", r.Operator)
		}
	case flipt.ComparisonType_BOOLEAN_COMPARISON_TYPE:
		if _, ok := booleanOperators[c.Operator]; !ok {
			return nil, ErrInvalidf("constraint operator %q is not valid for type boolean", r.Operator)
		}
	default:
		return nil, ErrInvalidf("invalid constraint type: %q", c.Type.String())
	}

	// unset value if operator does not require it
	if _, ok := noValueOperators[c.Operator]; ok {
		c.Value = ""
	}

	query := s.builder.Insert("constraints").
		Columns("id", "segment_key", "type", "property", "operator", "value", "created_at", "updated_at").
		Values(c.Id, c.SegmentKey, c.Type, c.Property, c.Operator, c.Value, &timestamp{c.CreatedAt}, &timestamp{c.UpdatedAt})

	if _, err := query.ExecContext(ctx); err != nil {
		switch ierr := err.(type) {
		case sqlite3.Error:
			Scan(&enabled)
	)

	if err != nil {
		if err == sql.ErrNoRows {
			return resp, ErrNotFoundf("flag %q", r.FlagKey)
		}
		return resp, err
	}

	if !enabled {
		return resp, ErrInvalidf("flag %q is disabled", r.FlagKey)
	}

	// get all rules for flag with their constraints if any
	rows, err := s.builder.Select("r.id, r.flag_key, r.segment_key, r.rank, c.id, c.type, c.property, c.operator, c.value").
		From("rules r").
		LeftJoin("constraints c ON (r.segment_key = c.segment_key)").
		Where(sq.Eq{"r.flag_key": r.FlagKey}).
		OrderBy("r.rank ASC").
		GroupBy("r.id, c.id").
		QueryContext(ctx)
	if err != nil {
		return resp, err
	}

	defer func() {
		if cerr := rows.Close(); cerr != nil && err == nil {
			err = cerr
		}
	}()

	rules := make([]*rule, 0)
	rulesByID := make(map[string]*rule)

	for rows.Next() {
		var (
			tempRule           rule
			optionalConstraint optionalConstraint
		)

		if err := rows.Scan(&tempRule.ID, &tempRule.FlagKey, &tempRule.SegmentKey, &tempRule.Rank, &optionalConstraint.ID, &optionalConstraint.Type, &optionalConstraint.Property, &optionalConstraint.Operator, &optionalConstraint.Value); err != nil {
			return resp, err
		}

		if existingRule, ok := rulesByID[tempRule.ID]; ok {
			// current rule we know about
			if optionalConstraint.ID.Valid {
				constraint := constraint{
					Type:     flipt.ComparisonType(optionalConstraint.Type.Int64),
					Property: optionalConstraint.Property.String,
					Operator: optionalConstraint.Operator.String,
					Value:    optionalConstraint.Value.String,
				}
				existingRule.Constraints = append(existingRule.Constraints, constraint)
			}
		} else {
			// haven't seen this rule before
			existingRule = &rule{
				ID:         tempRule.ID,
				FlagKey:    tempRule.FlagKey,
				SegmentKey: tempRule.SegmentKey,
				Rank:       tempRule.Rank,
			}

			if optionalConstraint.ID.Valid {
				constraint := constraint{
					Type:     flipt.ComparisonType(optionalConstraint.Type.Int64),
					Property: optionalConstraint.Property.String,
					Operator: optionalConstraint.Operator.String,
					Value:    optionalConstraint.Value.String,
				}
				existingRule.Constraints = append(existingRule.Constraints, constraint)
			}

			rulesByID[existingRule.ID] = existingRule
			rules = append(rules, existingRule)
		}
	}

	if err := rows.Err(); err != nil {
		return resp, err
	}
	if err := rows.Close(); err != nil {
		return resp, err
	}

	if len(rules) == 0 {
		logger.Debug("no rules match")
		return resp, nil
	}

}

func TestEvaluate_RolloutDistribution(t *testing.T) {
	flag, err := flagStore.CreateFlag(context.TODO(), &flipt.CreateFlagRequest{
		Key:         t.Name(),
		Name:        t.Name(),
		Description: "foo",
		Enabled:     true,
	})

	require.NoError(t, err)

	var variants []*flipt.Variant

	for _, req := range []*flipt.CreateVariantRequest{
		{
			FlagKey: flag.Key,
			Key:     fmt.Sprintf("foo_%s", t.Name()),
		},
		{
			FlagKey: flag.Key,
			Key:     fmt.Sprintf("bar_%s", t.Name()),
		},
	} {
		variant, err := flagStore.CreateVariant(context.TODO(), req)
		require.NoError(t, err)
		variants = append(variants, variant)
	}

	segment, err := segmentStore.CreateSegment(context.TODO(), &flipt.CreateSegmentRequest{
		Key:         t.Name(),
		Name:        t.Name(),
		Description: "foo",
	})

	require.NoError(t, err)

	_, err = segmentStore.CreateConstraint(context.TODO(), &flipt.CreateConstraintRequest{
		SegmentKey: segment.Key,
		Type:       flipt.ComparisonType_STRING_COMPARISON_TYPE,
		Property:   "bar",
		Operator:   opEQ,
		Value:      "baz",
	})

	require.NoError(t, err)

	rule, err := ruleStore.CreateRule(context.TODO(), &flipt.CreateRuleRequest{
		FlagKey:    flag.Key,
		SegmentKey: segment.Key,
	})

	require.NoError(t, err)

	for _, req := range []*flipt.CreateDistributionRequest{
		{
			FlagKey:   flag.Key,
			RuleId:    rule.Id,
			VariantId: variants[0].Id,
			Rollout:   50,
		},
		{
			FlagKey:   flag.Key,
			RuleId:    rule.Id,
			VariantId: variants[1].Id,
			Rollout:   50,
		},
	} {
		_, err := ruleStore.CreateDistribution(context.TODO(), req)
